SELECT id, event_id, experiment_id, visitor_id, group_id, event_type, event_name, client_event_id,
       properties_json, event_time, created_at
FROM pisces_experiment_event
WHERE experiment_id = #{experimentId}
  AND group_id = #{groupId}

  AND event_time >= #{startTime}


  AND event_time <= #{endTime}


  AND event_type IN

    #{eventType}


ORDER BY event_time ASC, id ASC
LIMIT #{limit} OFFSET #{offset}

SELECT e.id, e.event_id, e.experiment_id, e.visitor_id, e.group_id, e.event_type, e.event_name,
       e.client_event_id, e.properties_json, e.event_time, e.created_at
FROM pisces_experiment_event e
LEFT JOIN pisces_event_materialization m
  ON m.fact_kind = 'EVENT'
 AND m.fact_id = e.event_id
WHERE e.experiment_id = #{experimentId}
  AND e.group_id = #{groupId}
  AND m.fact_id IS NULL

  AND e.event_time >= #{startTime}


  AND e.event_time <= #{endTime}


  AND e.event_type IN

    #{eventType}


ORDER BY e.event_time ASC, e.id ASC

SELECT e.id, e.event_id, e.experiment_id, e.visitor_id, e.group_id, e.event_type, e.event_name,
       e.client_event_id, e.properties_json, e.event_time, e.created_at
FROM pisces_experiment_event e
LEFT JOIN pisces_event_materialization m
  ON m.fact_kind = 'EVENT'
 AND m.fact_id = e.event_id
WHERE e.experiment_id = #{experimentId}
  AND e.group_id = #{groupId}
  AND m.fact_id IS NULL

  AND e.event_time >= #{startTime}


  AND e.event_time <= #{endTime}


  AND e.event_type IN

    #{eventType}


ORDER BY e.event_time ASC, e.id ASC
LIMIT #{limit} OFFSET #{offset}

